  AND md5(q.question_text) = v.h;

-- 結果。4つの区分を1つの表にまとめる。
--   0.単問にした  … 四連問からほどいた設問の数
--   1.移した      … 何を何へ移したか（件数）
--   2.残った      … 正規名でないまま残った分野。0行なら完了
--   3.演習の一覧  … 演習画面に出る並び（公開中の設問）。記号は画面と同じ
WITH moved AS (
    SELECT b.exam_type, b.category AS before, q.category AS after, count(*) AS n
    FROM _before AS b JOIN quiz_question AS q ON q.id = b.id
    WHERE q.category <> b.category
    GROUP BY 1, 2, 3
),
leftover AS (
    SELECT exam_type, category, count(*) AS n FROM quiz_question
    WHERE (exam_type = 'KOKUSHI' AND category NOT IN ('消化管', '肝・胆・膵', '代謝・内分泌', '腎・泌尿器', '循環器', '呼吸器', '神経', '血液', '免疫・膠原病', '感染症', '救急・中毒・麻酔', '医学総論', '小児科', '婦人科・乳腺外科', '産科', '眼科', '耳鼻咽喉科', '整形外科', '精神科', '皮膚科', '泌尿器科', '放射線科', '公衆衛生', '必修問題'))
       OR (exam_type = 'CBT' AND category NOT IN ('消化器', '内分泌・代謝', '腎・泌尿器', '循環器', '呼吸器', '神経', '血液', '免疫・膠原病', '感染症', '腫瘍', '基礎医学', '皮膚', '運動器', '眼', '耳鼻咽喉', '精神', '小児（成長と発達）', '産婦人科', '救急・中毒・麻酔', '医学総論・公衆衛生・診療の基本'))
    GROUP BY 1, 2
),
canon_order AS (
    SELECT * FROM (VALUES
    ('CBT', '消化器', '0', '0'),
    ('CBT', '内分泌・代謝', '0', '1'),
    ('CBT', '腎・泌尿器', '0', '2'),
    ('CBT', '循環器', '0', '3'),
    ('CBT', '呼吸器', '0', '4'),
    ('CBT', '神経', '0', '5'),
    ('CBT', '血液', '0', '6'),
    ('CBT', '免疫・膠原病', '0', '7'),
    ('CBT', '感染症', '0', '8'),
    ('CBT', '腫瘍', '1', '9'),
    ('CBT', '基礎医学', '1', '10'),
    ('CBT', '皮膚', '1', '11'),
    ('CBT', '運動器', '1', '12'),
    ('CBT', '眼', '1', '13'),
    ('CBT', '耳鼻咽喉', '1', '14'),
    ('CBT', '精神', '1', '15'),
    ('CBT', '小児（成長と発達）', '1', '16'),
    ('CBT', '産婦人科', '1', '17'),
    ('CBT', '救急・中毒・麻酔', '1', '18'),
    ('CBT', '医学総論・公衆衛生・診療の基本', '1', '19'),
    ('KOKUSHI', '消化管', '0', '0'),
    ('KOKUSHI', '肝・胆・膵', '0', '1'),
    ('KOKUSHI', '代謝・内分泌', '0', '2'),
    ('KOKUSHI', '腎・泌尿器', '0', '3'),
    ('KOKUSHI', '循環器', '0', '4'),
    ('KOKUSHI', '呼吸器', '0', '5'),
    ('KOKUSHI', '神経', '0', '6'),
    ('KOKUSHI', '血液', '0', '7'),
    ('KOKUSHI', '免疫・膠原病', '0', '8'),
    ('KOKUSHI', '感染症', '0', '9'),
    ('KOKUSHI', '救急・中毒・麻酔', '1', '10'),
    ('KOKUSHI', '医学総論', '1', '11'),
    ('KOKUSHI', '小児科', '1', '12'),
    ('KOKUSHI', '婦人科・乳腺外科', '1', '13'),
    ('KOKUSHI', '産科', '1', '14'),
    ('KOKUSHI', '眼科', '1', '15'),
    ('KOKUSHI', '耳鼻咽喉科', '1', '16'),
    ('KOKUSHI', '整形外科', '1', '17'),
    ('KOKUSHI', '精神科', '1', '18'),
    ('KOKUSHI', '皮膚科', '1', '19'),
    ('KOKUSHI', '泌尿器科', '1', '20'),
    ('KOKUSHI', '放射線科', '1', '21'),
    ('KOKUSHI', '公衆衛生', '1', '22'),
    ('KOKUSHI', '必修問題', '1', '23')
    ) AS v(exam_type, category, grp, pos)
),
listing AS (
    SELECT q.exam_type, q.category, count(*) AS n,
           coalesce(o.grp::int, 2) AS grp, coalesce(o.pos::int, 999) AS pos
    FROM quiz_question AS q
    LEFT JOIN canon_order AS o ON o.exam_type = q.exam_type AND o.category = q.category
    WHERE q.status = 'published' AND q.visibility = 'public'
    GROUP BY 1, 2, 4, 5
)
SELECT 区分, 試験, 記号, 分野, 問題数 FROM (
    SELECT '0.単問にした' AS 区分, exam_type AS 試験, '' AS 記号,
           '四連問の設問' AS 分野, count(*) AS 問題数, 0 AS k, 0 AS r
    FROM _series GROUP BY exam_type
    UNION ALL
    SELECT '1.移した', exam_type, '', before || ' → ' || after, n, 1, 0
    FROM moved
    UNION ALL
    SELECT '2.残った', exam_type, '', category, n, 2, 0 FROM leftover
    UNION ALL
    SELECT '3.演習の一覧', exam_type,
           chr(64 + row_number() OVER (PARTITION BY exam_type
                                       ORDER BY grp, pos, category COLLATE "C")::int),
           category || CASE WHEN grp = 2 THEN '（正規名でない）' ELSE '' END, n,
           3, row_number() OVER (PARTITION BY exam_type ORDER BY grp, pos, category COLLATE "C")
    FROM listing
) AS report
ORDER BY k, 試験, r, 分野;

COMMIT;
